"use client";

import * as React from "react";
import { ArrowUpRight, Eye, EyeOff, KeyRound } from "lucide-react";
import { CodeInput } from "./code-input";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * AUTH CARD: sign-in that asks one thing at a time
 *
 *   email     sign-in providers, then the email field; your
 *             server decides what comes next (a password, a
 *             code or a link), the way identifier-first sign-in
 *             works at Google and Clerk
 *   identity  the email field doesn't go anywhere: its frame
 *             shrinks round the address into a chip as the
 *             providers fold away above it, and "Change" opens
 *             at its end to take you back
 *   step      each next step slides in from the right (Change
 *             slides back from the left) while the card eases
 *             to its new height; titles lift out and in
 *   code      the code boxes (code input) check as the last
 *             digit lands, and resend counts down
 *   link      "Check your inbox", with a button that opens the
 *             inbox itself for Gmail, Outlook, iCloud, Yahoo
 *             and Proton addresses
 *   done      a ring draws, a check draws inside it, "Signed in"
 *
 * The card never calls a service: every step is one async
 * function, so it fits Better Auth, Clerk, Supabase or Auth.js.
 * ───────────────────────────────────────────────────────── */

export type AuthNext = "password" | "code" | "link";
export type AuthStep = "email" | AuthNext | "reset" | "done";

export interface AuthProvider {
  id: string;
  label: string;
  icon?: React.ReactNode;
}

export interface AuthCardProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "title"
> {
  mode?: "sign-in" | "sign-up";
  /** Above the title: your mark. */
  logo?: React.ReactNode;
  /** Words per step: { email: { title, description }, code: { … }, … }. */
  copy?: Partial<Record<AuthStep, { title?: string; description?: string }>>;
  providers?: AuthProvider[];
  /** Starts a provider's sign-in; usually it redirects, so the button keeps spinning. */
  onProvider?: (id: string) => Promise<unknown> | unknown;
  /** Shows "Sign in with a passkey". Resolve when signed in. */
  onPasskey?: () => Promise<unknown>;
  /** Your server says what comes next for this address. Throw to say why not. */
  onEmail: (email: string) => Promise<AuthNext> | AuthNext;
  onPassword?: (email: string, password: string) => Promise<unknown>;
  /** Resolve when the code is right; throw when it isn't. */
  onCode?: (email: string, code: string) => Promise<unknown>;
  /** Sends the code or link again. */
  onResend?: (email: string) => Promise<unknown>;
  /** Shows "Forgot password?" on the password step; sends a reset link. */
  onForgot?: (email: string) => Promise<unknown>;
  /** After "Signed in" has shown, e.g. to redirect. */
  onSuccess?: () => void;
  defaultEmail?: string;
  codeLength?: number;
  /** Seconds before a code or link can be sent again. */
  resendAfter?: number;
  /** Under the card's content: terms, a link to sign up. */
  footer?: React.ReactNode;
}

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40";
const EMAIL = /^[^\s@]+@[^\s@]+\.[^\s@]+$/;
const SHAKE = [
  { transform: "none" },
  { transform: "translateX(-4px)" },
  { transform: "translateX(4px)" },
  { transform: "translateX(-2px)" },
  { transform: "none" },
];
const ORDER: AuthStep[] = [
  "email",
  "password",
  "code",
  "link",
  "reset",
  "done",
];
const INBOXES: [RegExp, string, string][] = [
  [
    /^(gmail|googlemail)\.com$/,
    "Gmail",
    "https://mail.google.com/mail/u/0/#inbox",
  ],
  [
    /^(outlook|hotmail|live|msn)\.[a-z.]+$/,
    "Outlook",
    "https://outlook.live.com/mail/",
  ],
  [/^(icloud|me|mac)\.com$/, "iCloud Mail", "https://www.icloud.com/mail"],
  [/^yahoo\.[a-z.]+$/, "Yahoo Mail", "https://mail.yahoo.com"],
  [
    /^(proton\.me|protonmail\.com|pm\.me)$/,
    "Proton Mail",
    "https://mail.proton.me",
  ],
];

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

const message = (e: unknown, fallback: string) =>
  e instanceof Error && e.message ? e.message : fallback;
const inboxFor = (email: string) => {
  const domain = email.split("@")[1]?.toLowerCase() ?? "";
  const hit = INBOXES.find(([re]) => re.test(domain));
  return hit ? { name: hit[1], href: hit[2] } : null;
};

/** A line that changes by lifting the old words out through a blur and the new ones in. */
function Line({
  text,
  className = "",
  reduced,
  as: Tag = "p",
  id,
}: {
  text: string;
  className?: string;
  reduced: boolean;
  as?: "p" | "h2";
  id?: string;
}) {
  const [shown, setShown] = React.useState(text);
  const [old, setOld] = React.useState<{ key: number; text: string }[]>([]);
  const key = React.useRef(0);
  const ref = React.useRef<HTMLSpanElement>(null);
  if (text !== shown) {
    if (!reduced && shown)
      setOld((o) => [...o, { key: ++key.current, text: shown }]);
    setShown(text);
  }
  React.useLayoutEffect(() => {
    if (reduced || !old.length) return;
    ref.current?.animate(
      [
        { opacity: 0, transform: "translateY(0.3em)", filter: "blur(4px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 380, delay: 80, easing: EASE, fill: "backwards" },
    );
  }, [shown]);
  return (
    <Tag id={id} className={`relative ${className}`}>
      <span ref={ref} className="block">
        {shown}
      </span>
      {old.map((o) => (
        <Leaving
          key={o.key}
          onDone={() => setOld((all) => all.filter((x) => x.key !== o.key))}
        >
          {o.text}
        </Leaving>
      ))}
    </Tag>
  );
}

function Leaving({
  children,
  onDone,
}: {
  children: React.ReactNode;
  onDone: () => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const a = ref.current?.animate(
      [
        { opacity: 1, filter: "blur(0px)" },
        { opacity: 0, transform: "translateY(-0.3em)", filter: "blur(4px)" },
      ],
      { duration: 220, easing: EASE, fill: "forwards" },
    );
    if (a) a.onfinish = onDone;
    return () => a?.cancel();
  }, []);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute inset-x-0 top-0 block"
    >
      {children}
    </span>
  );
}

function Fold({
  open,
  reduced,
  children,
}: {
  open: boolean;
  reduced: boolean;
  children: React.ReactNode;
}) {
  const [kept, setKept] = React.useState(children);
  if (open && kept !== children) {
    setKept(children);
  }
  return (
    <div
      className="grid"
      inert={!open}
      aria-hidden={!open || undefined}
      style={{
        gridTemplateRows: open ? "1fr" : "0fr",
        opacity: open ? 1 : 0,
        transition: reduced
          ? "none"
          : `grid-template-rows 460ms ${EASE}, opacity ${open ? 320 : 180}ms ${EASE}`,
      }}
    >
      <div className="min-h-0 overflow-clip [overflow-clip-margin:6px]">
        {open ? children : kept}
      </div>
    </div>
  );
}

/** The steps under the identity: the new one slides in from the side you went, the old one out the other way, and the box eases to fit. */
function Slides({
  step,
  dir,
  reduced,
  render,
}: {
  step: AuthStep;
  dir: number;
  reduced: boolean;
  render: (s: AuthStep) => React.ReactNode;
}) {
  const [faces, setFaces] = React.useState<
    { s: AuthStep; out: boolean; dir: number; enter: boolean }[]
  >([{ s: step, out: false, dir, enter: false }]);
  const [seen, setSeen] = React.useState(step);
  const boxRef = React.useRef<HTMLDivElement>(null);
  const height = React.useRef(0);
  // Clipped only while a step slides; at rest a menu can open past its edge.
  const [moving, setMoving] = React.useState(false);
  React.useEffect(() => {
    if (!moving) return;
    const timer = window.setTimeout(() => setMoving(false), 560);
    return () => window.clearTimeout(timer);
  }, [moving, step]);
  if (seen !== step) {
    setSeen(step);
    if (!reduced) setMoving(true);
    setFaces((f) => [
      ...f.filter((x) => x.out && x.s !== step && x.s !== seen),
      ...(reduced ? [] : [{ s: seen, out: true, dir, enter: false }]),
      { s: step, out: false, dir, enter: true },
    ]);
  }

  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el) return;
    height.current = el.offsetHeight;
    const observer = new ResizeObserver(
      () => (height.current = el.offsetHeight),
    );
    observer.observe(el);
    return () => observer.disconnect();
  }, []);

  React.useLayoutEffect(() => {
    const el = boxRef.current;
    if (!el || reduced) return;
    const to = el.offsetHeight;
    if (Math.abs(to - height.current) > 0.5)
      el.animate([{ height: `${height.current}px` }, { height: `${to}px` }], {
        duration: 460,
        easing: EASE,
      });
  }, [step]);

  return (
    <div
      ref={boxRef}
      className="relative [overflow-clip-margin:8px]"
      style={{ overflowY: moving ? "clip" : "visible" }}
    >
      {faces.map((f) => (
        <Face
          key={f.s}
          out={f.out}
          enter={f.enter}
          dir={f.dir}
          reduced={reduced}
          onGone={() =>
            setFaces((all) => all.filter((x) => !(x.s === f.s && x.out)))
          }
        >
          {render(f.s)}
        </Face>
      ))}
    </div>
  );
}

function Face({
  out,
  enter,
  dir,
  reduced,
  onGone,
  children,
}: {
  out: boolean;
  enter: boolean;
  dir: number;
  reduced: boolean;
  onGone: () => void;
  children: React.ReactNode;
}) {
  const ref = React.useRef<HTMLDivElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    // A face that comes back while it was still leaving drops its exit first.
    el.getAnimations().forEach((a) => a.cancel());
    if (reduced) return;
    if (out) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          {
            opacity: 0,
            transform: `translateX(${-dir * 28}px)`,
            filter: "blur(4px)",
          },
        ],
        { duration: 240, easing: EASE, fill: "forwards" },
      );
      a.onfinish = onGone;
      return;
    }
    if (!enter) return;
    el.animate(
      [
        {
          opacity: 0,
          transform: `translateX(${dir * 28}px)`,
          filter: "blur(4px)",
        },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 440, delay: 80, easing: EASE, fill: "backwards" },
    );
  }, [out]);
  return (
    <div
      ref={ref}
      inert={out}
      aria-hidden={out || undefined}
      className={out ? "pointer-events-none absolute inset-x-0 top-0" : ""}
    >
      {children}
    </div>
  );
}

/** "Resend in 0:28", rolling down; then Resend → Sending → Sent, and the clock starts again. */
function Resend({
  after,
  reduced,
  onResend,
}: {
  after: number;
  reduced: boolean;
  onResend: () => Promise<unknown>;
}) {
  const [since, setSince] = React.useState(() => Date.now());
  const [now, setNow] = React.useState(since);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const left = Math.max(0, since + after * 1000 - now);
  const counting = left > 0;
  React.useEffect(() => {
    if (!counting) return;
    const timer = window.setTimeout(
      () => setNow(Date.now()),
      1000 - (Date.now() % 1000) + 10,
    );
    return () => window.clearTimeout(timer);
  }, [counting, now]);
  React.useEffect(() => {
    if (status !== "success" && status !== "error") return;
    const timer = window.setTimeout(
      () => setStatus("idle"),
      status === "success" ? 1400 : 2400,
    );
    return () => window.clearTimeout(timer);
  }, [status]);
  const ready = !counting && status !== "pending" && status !== "success";
  const label =
    status === "pending"
      ? "Sending"
      : status === "success"
        ? "Sent"
        : status === "error"
          ? "Try again"
          : counting
            ? "Resend in"
            : "Resend";
  const s = Math.ceil(left / 1000);
  return (
    <button
      type="button"
      aria-disabled={!ready || undefined}
      aria-label={counting ? "Resend, available shortly" : "Resend"}
      onClick={async () => {
        if (!ready) return;
        setStatus("pending");
        try {
          await onResend();
          setStatus("success");
          setSince(Date.now());
          setNow(Date.now());
        } catch {
          setStatus("error");
        }
      }}
      className={`inline-flex h-7 cursor-pointer items-center rounded-full px-2.5 text-[12px] font-medium whitespace-nowrap tabular-nums transition-colors aria-disabled:cursor-default ${FOCUS} ${
        status === "error"
          ? "text-red-600 dark:text-red-400"
          : ready
            ? "text-foreground hover:bg-accent"
            : "text-muted-foreground"
      }`}
    >
      <TextMorph>{label}</TextMorph>
      <span
        aria-hidden="true"
        className="inline-grid"
        style={{
          gridTemplateColumns: counting && status === "idle" ? "1fr" : "0fr",
          opacity: counting && status === "idle" ? 1 : 0,
          transition: reduced
            ? "none"
            : `grid-template-columns 380ms ${EASE}, opacity 260ms ${EASE}`,
        }}
      >
        <span className="min-w-0 [clip-path:inset(-4px_0)]">
          <span className="inline-flex items-baseline pl-[0.25em]">
            <NumberRoll value={Math.floor(s / 60)} direction="down" />:
            <NumberRoll
              value={s % 60}
              format={{ minimumIntegerDigits: 2 }}
              direction="down"
            />
          </span>
        </span>
      </span>
    </button>
  );
}

/** A ring that draws itself, then a check inside it. */
function Done({ reduced }: { reduced: boolean }) {
  const ring = React.useRef<SVGCircleElement>(null);
  const check = React.useRef<SVGPathElement>(null);
  React.useLayoutEffect(() => {
    if (reduced) return;
    ring.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 640,
      delay: 120,
      easing: EASE,
      fill: "backwards",
    });
    check.current?.animate([{ strokeDashoffset: 1 }, { strokeDashoffset: 0 }], {
      duration: 420,
      delay: 560,
      easing: EASE,
      fill: "backwards",
    });
  }, [reduced]);
  return (
    <svg
      viewBox="0 0 48 48"
      fill="none"
      aria-hidden="true"
      className="size-12 text-emerald-600 dark:text-emerald-400"
    >
      <circle cx="24" cy="24" r="22.5" stroke="var(--border)" strokeWidth="1" />
      <circle
        ref={ring}
        cx="24"
        cy="24"
        r="22.5"
        stroke="currentColor"
        strokeWidth="1.25"
        pathLength={1}
        strokeDasharray={1}
        transform="rotate(-90 24 24)"
        strokeDashoffset={0}
      />
      <path
        ref={check}
        d="M16.5 24.5 21.5 29.5 31.5 18.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        strokeDashoffset={0}
      />
    </svg>
  );
}

export function AuthCard({
  mode = "sign-in",
  logo,
  copy,
  providers = [],
  onProvider,
  onPasskey,
  onEmail,
  onPassword,
  onCode,
  onResend,
  onForgot,
  onSuccess,
  defaultEmail = "",
  codeLength = 6,
  resendAfter = 30,
  footer,
  className = "",
  ...props
}: AuthCardProps) {
  const id = React.useId();
  const reduced = useReducedMotion();
  const [step, setStep] = React.useState<AuthStep>("email");
  const [dir, setDir] = React.useState(1);
  const [email, setEmail] = React.useState(defaultEmail);
  const [password, setPassword] = React.useState("");
  const [showPassword, setShowPassword] = React.useState(false);
  const [busy, setBusy] = React.useState<string | null>(null);
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  const [error, setError] = React.useState<string | null>(null);
  const [announce, setAnnounce] = React.useState("");
  const [chipWidth, setChipWidth] = React.useState(0);
  const shellRef = React.useRef<HTMLDivElement>(null);
  const emailRef = React.useRef<HTMLInputElement>(null);
  const mirrorRef = React.useRef<HTMLSpanElement>(null);
  const changeRef = React.useRef<HTMLButtonElement>(null);
  const passwordRef = React.useRef<HTMLInputElement>(null);
  const bodyRef = React.useRef<HTMLDivElement>(null);
  const identity = step !== "email";
  const signUp = mode === "sign-up";

  const words: Record<AuthStep, { title: string; description: string }> = {
    email: {
      title: signUp ? "Create your account" : "Sign in",
      description: signUp
        ? "Start with your work email."
        : "Welcome back. Use the email you signed up with.",
    },
    password: { title: "Enter your password", description: "" },
    code: {
      title: "Check your email",
      description: "We sent you a code. It works for 10 minutes.",
    },
    link: {
      title: "Check your inbox",
      description: "We sent you a sign-in link. It works for 10 minutes.",
    },
    reset: {
      title: "Check your inbox",
      description: "We sent a link to reset your password.",
    },
    done: {
      title: signUp ? "You're in" : "Signed in",
      description: "Taking you to your workspace.",
    },
  };
  const title = copy?.[step]?.title ?? words[step].title;
  const description = copy?.[step]?.description ?? words[step].description;

  const go = (next: AuthStep) => {
    setDir(ORDER.indexOf(next) >= ORDER.indexOf(step) ? 1 : -1);
    setError(null);
    setStatus("idle");
    setStep(next);
    setAnnounce(copy?.[next]?.title ?? words[next].title);
  };

  const shake = (el: Element | null | undefined) => {
    if (!reduced) el?.animate(SHAKE, { duration: 380, easing: "ease-out" });
  };

  // The chip is as wide as the address plus "Change".
  React.useLayoutEffect(() => {
    const m = mirrorRef.current;
    const c = changeRef.current;
    if (!m || !c) return;
    const w = Math.ceil(m.offsetWidth + c.offsetWidth + 6);
    setChipWidth((p) => (p === w ? p : w));
  }, [email, identity]);

  // Each step puts focus on the thing to do next.
  React.useEffect(() => {
    const body = bodyRef.current;
    if (step === "email") {
      if (dir < 0) emailRef.current?.select();
      return;
    }
    const timer = window.setTimeout(
      () => {
        if (step === "password")
          passwordRef.current?.focus({ preventScroll: true });
        else
          body
            ?.querySelector<HTMLElement>(
              "[data-autofocus], input, a[href], button:not([aria-disabled])",
            )
            ?.focus({ preventScroll: true });
      },
      reduced ? 0 : 120,
    );
    return () => window.clearTimeout(timer);
  }, [step]);

  React.useEffect(() => {
    if (step !== "done" || !onSuccess) return;
    const timer = window.setTimeout(onSuccess, reduced ? 400 : 1300);
    return () => window.clearTimeout(timer);
  }, [step, onSuccess, reduced]);

  const submitEmail = async () => {
    if (status === "pending") return;
    const value = email.trim();
    if (!EMAIL.test(value)) {
      setError(
        value
          ? `“${value}” doesn't look like an email address.`
          : "Enter your email address.",
      );
      shake(shellRef.current);
      emailRef.current?.focus();
      return;
    }
    setEmail(value);
    setStatus("pending");
    setError(null);
    try {
      const next = await onEmail(value);
      go(next);
    } catch (e) {
      setStatus("error");
      setError(message(e, "We couldn't check that address. Try again."));
      shake(shellRef.current);
    }
  };

  const submitPassword = async () => {
    if (status === "pending" || !onPassword) return;
    if (!password) {
      setError("Enter your password.");
      shake(passwordRef.current?.parentElement);
      return;
    }
    setStatus("pending");
    setError(null);
    try {
      await onPassword(email, password);
      go("done");
    } catch (e) {
      setStatus("error");
      setError(message(e, "That password isn't right."));
      shake(passwordRef.current?.parentElement);
      passwordRef.current?.select();
    }
  };

  const runProvider = async (key: string, run: () => unknown) => {
    if (busy) return;
    setBusy(key);
    setError(null);
    try {
      await run();
      // A redirect never gets here; a popup or a passkey does.
      go("done");
    } catch (e) {
      setBusy(null);
      setError(
        message(
          e,
          key === "passkey"
            ? "Passkey sign-in didn't finish."
            : "That sign-in didn't finish. Try again.",
        ),
      );
    }
  };

  const errorLine = (
    <Fold open={Boolean(error)} reduced={reduced}>
      <p
        id={`${id}-error`}
        className="pt-2 text-[12px] text-red-600 dark:text-red-400"
      >
        {error}
      </p>
    </Fold>
  );

  const inbox = inboxFor(email);
  const render = (s: AuthStep): React.ReactNode => {
    if (s === "email")
      return (
        <div className="pt-3">
          <StatusButton
            type="submit"
            status={status}
            labels={{
              idle: "Continue",
              pending: "Checking",
              success: "Continue",
              error: "Try again",
            }}
            className="w-full"
          />
          {onPasskey && (
            <button
              type="button"
              onClick={() => runProvider("passkey", onPasskey)}
              aria-busy={busy === "passkey" || undefined}
              className={`mt-2 inline-flex h-9 w-full cursor-pointer items-center justify-center gap-2 rounded-full text-[13px] font-medium text-muted-foreground transition-colors hover:bg-accent hover:text-foreground aria-busy:cursor-default ${FOCUS}`}
            >
              {busy === "passkey" ? (
                <span className="size-3.5 animate-spin rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none" />
              ) : (
                <KeyRound
                  className="size-4"
                  strokeWidth={1.75}
                  aria-hidden="true"
                />
              )}
              <TextMorph>
                {busy === "passkey"
                  ? "Waiting for your passkey"
                  : "Sign in with a passkey"}
              </TextMorph>
            </button>
          )}
        </div>
      );
    if (s === "password")
      return (
        <div className="pt-3">
          <label
            htmlFor={`${id}-password`}
            className="text-[12px] font-medium text-muted-foreground"
          >
            Password
          </label>
          <div
            className={`mt-1.5 flex h-10 items-center rounded-[12px] pr-1 transition-shadow ${error ? "shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_45%,transparent)]" : "shadow-[inset_0_0_0_1px_var(--border)] focus-within:shadow-[inset_0_0_0_1px_var(--ring)]"}`}
          >
            <input
              ref={passwordRef}
              id={`${id}-password`}
              type={showPassword ? "text" : "password"}
              autoComplete={signUp ? "new-password" : "current-password"}
              value={password}
              onChange={(e) => {
                setPassword(e.target.value);
                setError(null);
                if (status === "error") setStatus("idle");
              }}
              aria-invalid={Boolean(error) || undefined}
              aria-describedby={error ? `${id}-error` : undefined}
              className="h-full min-w-0 flex-1 bg-transparent px-3 text-[16px] text-foreground outline-none [@media(pointer:fine)]:text-[14px]"
            />
            <button
              type="button"
              aria-label={showPassword ? "Hide password" : "Show password"}
              aria-pressed={showPassword}
              onClick={() => setShowPassword((v) => !v)}
              className={`relative grid size-8 shrink-0 cursor-pointer place-items-center rounded-full text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
            >
              {[false, true].map((on) => (
                <span
                  key={String(on)}
                  aria-hidden="true"
                  className="absolute inset-0 grid place-items-center"
                  style={{
                    opacity: showPassword === on ? 1 : 0,
                    transform: showPassword === on ? "none" : "scale(0.6)",
                    filter:
                      showPassword === on || reduced ? "none" : "blur(3px)",
                    transition: reduced
                      ? "none"
                      : `opacity 240ms ${EASE}, transform 360ms ${EASE}, filter 240ms ${EASE}`,
                  }}
                >
                  {on ? (
                    <EyeOff className="size-4" strokeWidth={1.75} />
                  ) : (
                    <Eye className="size-4" strokeWidth={1.75} />
                  )}
                </span>
              ))}
            </button>
          </div>
          {errorLine}
          <div className="mt-3 flex items-center justify-between gap-2">
            {onForgot ? (
              <ForgotButton
                onForgot={async () => {
                  await onForgot(email);
                  go("reset");
                }}
              />
            ) : (
              <span />
            )}
            <StatusButton
              type="submit"
              status={status}
              labels={{
                idle: "Sign in",
                pending: "Signing in",
                success: "Signed in",
                error: "Try again",
              }}
            />
          </div>
        </div>
      );
    if (s === "code")
      return (
        <div className="pt-4">
          <CodeInput
            length={codeLength}
            autoFocus
            onComplete={async (code) => {
              await onCode?.(email, code);
              window.setTimeout(() => go("done"), reduced ? 0 : 900);
              return true;
            }}
            onResend={onResend ? () => onResend(email) : undefined}
            resendAfter={resendAfter}
          />
        </div>
      );
    if (s === "link" || s === "reset")
      return (
        <div className="flex flex-wrap items-center gap-2 pt-4">
          {inbox && (
            <a
              data-autofocus=""
              href={inbox.href}
              target="_blank"
              rel="noopener noreferrer"
              className={`inline-flex h-9 cursor-pointer items-center gap-1.5 rounded-full bg-primary px-4 text-[13px] font-medium text-primary-foreground transition-colors hover:bg-primary/90 ${FOCUS}`}
            >
              Open {inbox.name}
              <ArrowUpRight
                className="size-3.5"
                strokeWidth={2}
                aria-hidden="true"
              />
            </a>
          )}
          {onResend && (
            <Resend
              after={resendAfter}
              reduced={reduced}
              onResend={() => onResend(email)}
            />
          )}
        </div>
      );
    return (
      <div className="flex flex-col items-center pt-5 pb-1 text-center">
        <Done reduced={reduced} />
      </div>
    );
  };

  return (
    <div
      className={`w-full rounded-[22px] border border-border bg-background p-5 text-foreground sm:p-6 ${className}`}
      {...props}
    >
      {logo && <div className="mb-4">{logo}</div>}
      <Line
        as="h2"
        id={`${id}-title`}
        text={title}
        reduced={reduced}
        className="text-[19px] font-medium tracking-[-0.02em]"
      />
      <Fold open={Boolean(description)} reduced={reduced}>
        <Line
          text={description}
          reduced={reduced}
          className="mt-1 text-[13px] leading-[1.5] text-muted-foreground"
        />
      </Fold>

      <form
        noValidate
        aria-labelledby={`${id}-title`}
        onSubmit={(e) => {
          e.preventDefault();
          if (step === "email") submitEmail();
          else if (step === "password") submitPassword();
        }}
      >
        {/* Providers fold away above the address once it's chosen. */}
        <Fold open={!identity && providers.length > 0} reduced={reduced}>
          <div className="pt-5">
            <div
              className={`grid gap-2 ${providers.length > 1 ? "grid-cols-2" : ""}`}
            >
              {providers.map((p) => (
                <button
                  key={p.id}
                  type="button"
                  onClick={() =>
                    onProvider && runProvider(p.id, () => onProvider(p.id))
                  }
                  aria-busy={busy === p.id || undefined}
                  disabled={Boolean(busy) && busy !== p.id}
                  className={`inline-flex h-10 cursor-pointer items-center justify-center gap-2 rounded-full text-[13px] font-medium shadow-[inset_0_0_0_1px_var(--border)] transition-[background-color,opacity] duration-200 hover:bg-accent disabled:cursor-default disabled:opacity-40 aria-busy:cursor-default ${FOCUS}`}
                >
                  <span
                    className="relative grid size-4 place-items-center [&_svg]:size-4"
                    aria-hidden="true"
                  >
                    <span
                      className="absolute inset-0 grid place-items-center"
                      style={{
                        opacity: busy === p.id ? 0 : 1,
                        transform: busy === p.id ? "scale(0.6)" : "none",
                        transition: reduced
                          ? "none"
                          : `opacity 200ms ${EASE}, transform 320ms ${EASE}`,
                      }}
                    >
                      {p.icon}
                    </span>
                    <span
                      className={`absolute inset-0.5 rounded-full border-[1.5px] border-current border-t-transparent motion-reduce:animate-none ${busy === p.id ? "animate-spin" : ""}`}
                      style={{
                        opacity: busy === p.id ? 1 : 0,
                        transition: reduced ? "none" : `opacity 200ms ${EASE}`,
                      }}
                    />
                  </span>
                  {p.label}
                </button>
              ))}
            </div>
            <div
              className="mt-5 flex items-center gap-3 text-[11.5px] text-muted-foreground"
              aria-hidden="true"
            >
              <span className="h-px flex-1 bg-border" />
              or
              <span className="h-px flex-1 bg-border" />
            </div>
          </div>
        </Fold>

        <div className="pt-4">
          {!identity && (
            <label
              htmlFor={`${id}-email`}
              className="mb-1.5 block text-[12px] font-medium text-muted-foreground"
            >
              Email
            </label>
          )}
          {/* The address: a field, then the same frame shrunk round it as a chip. */}
          <div
            ref={shellRef}
            className="relative flex items-center overflow-hidden"
            style={{
              width: identity ? chipWidth || "auto" : "100%",
              maxWidth: "100%",
              height: identity ? 32 : 40,
              borderRadius: identity ? 16 : 12,
              boxShadow: identity
                ? "inset 0 0 0 1px var(--border)"
                : error && step === "email"
                  ? "inset 0 0 0 1px color-mix(in oklab, var(--color-red-500) 45%, transparent)"
                  : undefined,
              transition: reduced
                ? "none"
                : `width 520ms ${EASE}, height 520ms ${EASE}, border-radius 520ms ${EASE}, box-shadow 200ms`,
            }}
          >
            <span
              aria-hidden="true"
              className={`pointer-events-none absolute inset-0 rounded-[inherit] transition-shadow duration-200 ${identity || (error && step === "email") ? "" : "shadow-[inset_0_0_0_1px_var(--border)] [:focus-within>&]:shadow-[inset_0_0_0_1px_var(--ring)]"}`}
            />
            <span
              ref={mirrorRef}
              aria-hidden="true"
              className="pointer-events-none invisible absolute left-0 top-0 whitespace-pre px-3 text-[16px] [@media(pointer:fine)]:text-[14px]"
            >
              {email || " "}
            </span>
            <input
              ref={emailRef}
              id={`${id}-email`}
              type="email"
              inputMode="email"
              autoComplete={onPasskey ? "username webauthn" : "email"}
              placeholder="you@company.com"
              value={email}
              readOnly={identity || status === "pending"}
              tabIndex={identity ? -1 : undefined}
              aria-label={identity ? `Signing in as ${email}` : undefined}
              aria-invalid={(Boolean(error) && step === "email") || undefined}
              aria-describedby={
                error && step === "email" ? `${id}-error` : undefined
              }
              onChange={(e) => {
                setEmail(e.target.value);
                setError(null);
                if (status === "error") setStatus("idle");
              }}
              className="h-full min-w-0 flex-1 bg-transparent px-3 text-[16px] text-foreground outline-none placeholder:text-muted-foreground/70 [@media(pointer:fine)]:text-[14px]"
            />
            <span
              className="inline-grid shrink-0"
              style={{
                gridTemplateColumns:
                  identity && step !== "done" ? "1fr" : "0fr",
                opacity: identity && step !== "done" ? 1 : 0,
                transition: reduced
                  ? "none"
                  : `grid-template-columns 420ms ${EASE} ${identity ? 160 : 0}ms, opacity 260ms ${EASE} ${identity ? 220 : 0}ms`,
              }}
              inert={!identity || step === "done"}
            >
              <span className="min-w-0 overflow-clip">
                <button
                  ref={changeRef}
                  type="button"
                  onClick={() => {
                    setPassword("");
                    go("email");
                  }}
                  className={`mr-1 h-6 cursor-pointer rounded-full px-2 text-[12px] font-medium whitespace-nowrap text-muted-foreground transition-colors hover:bg-accent hover:text-foreground ${FOCUS}`}
                >
                  Change
                </button>
              </span>
            </span>
          </div>
          {step === "email" && errorLine}
        </div>

        <div ref={bodyRef}>
          <Slides step={step} dir={dir} reduced={reduced} render={render} />
        </div>
      </form>

      {footer && (
        <Fold open={step === "email"} reduced={reduced}>
          <div className="pt-5 text-center text-[12px] text-muted-foreground [&_a]:font-medium [&_a]:text-foreground [&_a]:underline-offset-2 hover:[&_a]:underline">
            {footer}
          </div>
        </Fold>
      )}

      <span className="sr-only" role="status">
        {announce}
      </span>
    </div>
  );
}

function ForgotButton({ onForgot }: { onForgot: () => Promise<void> }) {
  const [status, setStatus] = React.useState<ActionStatus>("idle");
  return (
    <button
      type="button"
      aria-disabled={status === "pending" || undefined}
      onClick={async () => {
        if (status === "pending") return;
        setStatus("pending");
        try {
          await onForgot();
        } catch {
          setStatus("error");
        }
      }}
      className={`-ml-2 h-7 cursor-pointer rounded-full px-2 text-[12px] font-medium transition-colors hover:bg-accent ${FOCUS} ${status === "error" ? "text-red-600 dark:text-red-400" : "text-muted-foreground hover:text-foreground"}`}
    >
      <TextMorph>
        {status === "pending"
          ? "Sending a link"
          : status === "error"
            ? "Couldn't send it. Try again"
            : "Forgot password?"}
      </TextMorph>
    </button>
  );
}

"use client";

import * as React from "react";
import { NumberRoll } from "./number-roll";
import { StatusButton, type ActionStatus } from "./status-button";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * CODE INPUT: the six boxes, done properly
 *
 *   typing     each digit rises into its box out of a blur; the
 *              box you're on carries a blinking caret; deleting
 *              lifts a digit away rather than blinking it out
 *   paste      a pasted or autofilled code drops in one box after
 *              another
 *   checking   with every box full, the row carries a sweep of
 *              light while onComplete runs
 *   wrong      the row shakes, the boxes turn red, the label
 *              says so, and the digits clear from the right
 *   right      the digits stay where they are while the boxes'
 *              own outlines melt into one pill around them; a
 *              check draws itself at its end, "Verified"
 *   resend     "Resend in 0:28", the seconds rolling down, then
 *              a Resend button that spins, ticks and starts the
 *              clock again
 *
 * One real input sits over the boxes (one-time-code autofill,
 * paste and the numeric keyboard all just work); the boxes are
 * only what you see.
 * ───────────────────────────────────────────────────────── */

export interface CodeInputProps extends Omit<
  React.HTMLAttributes<HTMLDivElement>,
  "onChange" | "defaultValue"
> {
  length?: number;
  value?: string;
  defaultValue?: string;
  onValueChange?: (value: string) => void;
  /** Runs when every box is filled. Resolve (or return true) to accept; throw or return false to reject. */
  onComplete?: (code: string) => Promise<boolean | void> | boolean | void;
  /** Shows the resend line; the clock starts on mount and after each resend. */
  onResend?: () => Promise<unknown> | void;
  /** Seconds before a code can be resent. */
  resendAfter?: number;
  label?: string;
  /** Box groups, e.g. [3, 3] puts a dash between two threes. */
  groups?: number[];
  /** Letters as well as digits. */
  alphanumeric?: boolean;
  autoFocus?: boolean;
}

type Phase = "idle" | "checking" | "wrong" | "right";

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SHEEN =
  "[mask-image:linear-gradient(90deg,rgb(0_0_0/0.4)_35%,#000_50%,rgb(0_0_0/0.4)_65%)] [mask-size:200%_100%] animate-[ui-sheen_1.4s_linear_infinite] motion-reduce:animate-none motion-reduce:[mask-image:none]";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** One character: rises in out of a blur when it arrives, lifts away when it goes. */
function Glyph({
  char,
  delay,
  reduced,
}: {
  char: string | undefined;
  delay: number;
  reduced: boolean;
}) {
  const [shown, setShown] = React.useState(char);
  const [leaving, setLeaving] = React.useState(false);
  const ref = React.useRef<HTMLSpanElement>(null);
  // The character last drawn rising in: the one there on mount never rises, a new one always does.
  const risen = React.useRef(char);
  if (char !== undefined && (char !== shown || leaving)) {
    setShown(char);
    setLeaving(false);
  } else if (
    char === undefined &&
    shown !== undefined &&
    (!leaving || reduced)
  ) {
    // With reduced motion a character just goes; otherwise it lifts away first.
    if (reduced) {
      setShown(undefined);
      setLeaving(false);
    } else setLeaving(true);
  }

  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el || reduced) return;
    if (leaving) {
      const a = el.animate(
        [
          { opacity: 1, transform: "none", filter: "blur(0px)" },
          { opacity: 0, transform: "translateY(-35%)", filter: "blur(4px)" },
        ],
        { duration: 200, delay, easing: EASE, fill: "forwards" },
      );
      a.onfinish = () => setShown(undefined);
      return () => a.cancel();
    }
    if (shown === undefined) {
      risen.current = undefined;
      return;
    }
    if (risen.current === shown) return;
    risen.current = shown;
    const a = el.animate(
      [
        { opacity: 0, transform: "translateY(45%)", filter: "blur(4px)" },
        { opacity: 1, transform: "none", filter: "blur(0px)" },
      ],
      { duration: 300, delay, easing: EASE, fill: "backwards" },
    );
    return () => a.cancel();
  }, [shown, leaving]);

  if (shown === undefined) return null;
  return (
    <span ref={ref} className="inline-block">
      {shown}
    </span>
  );
}

export function CodeInput({
  length = 6,
  value,
  defaultValue = "",
  onValueChange,
  onComplete,
  onResend,
  resendAfter = 30,
  label = `Enter the ${length}-digit code`,
  groups,
  alphanumeric = false,
  autoFocus,
  className = "",
  ...props
}: CodeInputProps) {
  const reduced = useReducedMotion();
  const id = React.useId();
  const [own, setOwn] = React.useState(defaultValue.slice(0, length));
  const code = (value ?? own).slice(0, length);
  const [phase, setPhase] = React.useState<Phase>("idle");
  const [focused, setFocused] = React.useState(false);
  const [arrival, setArrival] = React.useState({
    length: code.length,
    from: code.length,
  });
  const [clearing, setClearing] = React.useState(false);
  // Resend clock: whole seconds, running from the start when there's a resend, and again after each one.
  const [left, setLeft] = React.useState<number | null>(
    onResend ? resendAfter : null,
  );
  const [resend, setResend] = React.useState<ActionStatus>("idle");
  const inputRef = React.useRef<HTMLInputElement>(null);
  const rowRef = React.useRef<HTMLDivElement>(null);

  // How the new characters arrived: one typed, or several at once (paste, autofill) to cascade in.
  if (arrival.length !== code.length)
    setArrival({ length: code.length, from: arrival.length });
  const arrivedFrom = arrival.from;

  const setCode = (next: string) => {
    if (value === undefined) setOwn(next);
    onValueChange?.(next);
  };

  const startClock = React.useCallback(
    () => setLeft(resendAfter),
    [resendAfter],
  );
  React.useEffect(() => {
    if (left === null || left <= 0) return;
    const timer = window.setTimeout(
      () => setLeft((s) => (s === null ? s : s - 1)),
      1000,
    );
    return () => window.clearTimeout(timer);
  }, [left]);

  const check = async (full: string) => {
    if (!onComplete) return;
    setPhase("checking");
    let ok = true;
    try {
      ok = (await onComplete(full)) !== false;
    } catch {
      ok = false;
    }
    if (ok) {
      setPhase("right");
      inputRef.current?.blur();
      return;
    }
    setPhase("wrong");
    if (!reduced) {
      rowRef.current?.animate(
        [
          { transform: "none" },
          { transform: "translateX(-5px)" },
          { transform: "translateX(5px)" },
          { transform: "translateX(-3px)" },
          { transform: "none" },
        ],
        { duration: 380, easing: "ease-out" },
      );
    }
    // Let the shake land, then clear from the right and start again at the first box.
    window.setTimeout(
      () => {
        setClearing(true);
        setCode("");
        inputRef.current?.focus();
        window.setTimeout(() => setClearing(false), 400);
      },
      reduced ? 0 : 650,
    );
  };

  const onChange = (e: React.ChangeEvent<HTMLInputElement>) => {
    if (phase === "checking" || phase === "right") return;
    const raw = e.target.value;
    const clean = (
      alphanumeric
        ? raw.replace(/[^a-z0-9]/gi, "").toUpperCase()
        : raw.replace(/\D/g, "")
    ).slice(0, length);
    if (phase === "wrong") setPhase("idle");
    setCode(clean);
  };

  // A full code, however it arrived (typed, pasted, autofilled or set from outside), gets checked once.
  const lastLength = React.useRef(code.length);
  React.useEffect(() => {
    if (
      code.length === length &&
      lastLength.current < length &&
      (phase === "idle" || phase === "wrong")
    )
      check(code);
    lastLength.current = code.length;
  }, [code]);

  const doResend = async () => {
    if (!onResend || resend === "pending") return;
    setResend("pending");
    try {
      await onResend();
      setResend("success");
      window.setTimeout(
        () => {
          setResend("idle");
          startClock();
        },
        reduced ? 0 : 1100,
      );
    } catch {
      setResend("error");
    }
  };

  // Where the dashes go between groups.
  const breaks = new Set<number>();
  if (groups)
    groups.reduce((at, size) => (breaks.add(at + size), at + size), 0);
  const right = phase === "right";
  const wrong = phase === "wrong";
  const active =
    focused && phase !== "checking" && !right
      ? Math.min(code.length, length - 1)
      : -1;
  const labelText = right
    ? "Verified"
    : wrong
      ? "That code didn't work"
      : phase === "checking"
        ? "Checking the code"
        : label;

  return (
    <div className={`@container w-full ${className}`} {...props}>
      <label
        htmlFor={id}
        className={`block text-[12.5px] transition-colors duration-300 ${wrong ? "text-red-600 dark:text-red-400" : "text-muted-foreground"}`}
      >
        <TextMorph>{labelText}</TextMorph>
      </label>

      <div className="relative mt-2 w-fit">
        <input
          ref={inputRef}
          id={id}
          value={code}
          onChange={onChange}
          onFocus={(e) => {
            setFocused(true);
            const end = e.currentTarget.value.length;
            e.currentTarget.setSelectionRange(end, end);
          }}
          onBlur={() => setFocused(false)}
          onSelect={(e) => {
            // The caret always sits at the end; the boxes show where you are.
            const el = e.currentTarget;
            if (el.selectionStart !== el.value.length)
              el.setSelectionRange(el.value.length, el.value.length);
          }}
          readOnly={phase === "checking" || right}
          autoFocus={autoFocus}
          autoComplete="one-time-code"
          inputMode={alphanumeric ? "text" : "numeric"}
          pattern={alphanumeric ? "[A-Za-z0-9]*" : "[0-9]*"}
          maxLength={length}
          spellCheck={false}
          aria-invalid={wrong || undefined}
          className="absolute inset-0 z-10 h-full w-full cursor-text bg-transparent text-[16px] text-transparent caret-transparent opacity-0 outline-none [&::selection]:bg-transparent"
        />

        {/* The boxes, and the one pill they become when the code is right. */}
        <div
          ref={rowRef}
          aria-hidden="true"
          className={`relative flex items-center gap-[var(--code-gap,8px)] rounded-[12px] @max-[19rem]:gap-[var(--code-gap,4px)] transition-[box-shadow,background-color] duration-500 ${phase === "checking" ? SHEEN : ""}`}
          style={{
            boxShadow: right
              ? "0 0 0 1px color-mix(in oklab, #10b981 55%, transparent)"
              : "0 0 0 1px transparent",
            background: right
              ? "color-mix(in oklab, #10b981 6%, var(--background))"
              : "transparent",
            transitionTimingFunction: EASE,
          }}
        >
          {Array.from({ length }, (_, i) => {
            const char = code[i];
            const isActive = i === active;
            const cascade =
              !clearing && code.length - arrivedFrom > 1 && i >= arrivedFrom
                ? (i - arrivedFrom) * 45
                : 0;
            const exitDelay = clearing ? (length - 1 - i) * 30 : 0;
            return (
              <React.Fragment key={i}>
                {/* The dash fades but keeps its place, so no digit moves when the code is right. */}
                {breaks.has(i) && i > 0 && (
                  <span
                    className="mx-0.5 block h-px w-2 bg-muted-foreground/40 transition-opacity duration-300"
                    style={{ opacity: right ? 0 : 1 }}
                  />
                )}
                <span
                  className="relative flex h-10 w-[34px] shrink-0 items-center justify-center text-[18px] font-medium tabular-nums text-foreground transition-[box-shadow,background-color] duration-300 @max-[19rem]:w-[30px] @min-[22rem]:h-11 @min-[22rem]:w-9 @min-[22rem]:text-[19px]"
                  style={{
                    borderRadius: 10,
                    boxShadow: right
                      ? "inset 0 0 0 1px transparent"
                      : wrong
                        ? "inset 0 0 0 1px color-mix(in oklab, #ef4444 60%, transparent)"
                        : isActive
                          ? "inset 0 0 0 1.5px color-mix(in oklab, var(--ring) 70%, transparent)"
                          : "inset 0 0 0 1px var(--border)",
                    background: right ? "transparent" : "var(--background)",
                  }}
                >
                  <Glyph
                    char={char}
                    delay={char !== undefined ? cascade : exitDelay}
                    reduced={reduced}
                  />
                  {/* The caret, blinking only in the box you're on. */}
                  {isActive && char === undefined && (
                    <span className="absolute h-5 w-px bg-foreground animate-[ui-blink_1s_steps(1)_infinite] motion-reduce:animate-none" />
                  )}
                </span>
              </React.Fragment>
            );
          })}

          {/* The check at the end of the pill: the pill grows to the right for it, the digits stay put. */}
          <span
            className="grid transition-[grid-template-columns,opacity] duration-500"
            style={{
              gridTemplateColumns: right ? "1fr" : "0fr",
              opacity: right ? 1 : 0,
              transitionTimingFunction: EASE,
            }}
          >
            <span className="flex min-w-0 items-center overflow-hidden">
              <svg
                viewBox="0 0 16 16"
                className="ml-1 mr-3 size-4 shrink-0 text-emerald-600"
                fill="none"
              >
                <path
                  d="M3.5 8.5 6.5 11.5 12.5 4.5"
                  stroke="currentColor"
                  strokeWidth="2"
                  strokeLinecap="round"
                  strokeLinejoin="round"
                  pathLength={1}
                  strokeDasharray={1}
                  style={{
                    strokeDashoffset: right ? 0 : 1,
                    transition: reduced
                      ? "none"
                      : `stroke-dashoffset 420ms ${EASE} 260ms`,
                  }}
                />
              </svg>
            </span>
          </span>
        </div>
      </div>

      {onResend && !right && (
        <div className="mt-3 flex h-7 items-center gap-1.5 text-[12px] text-muted-foreground">
          <span>Didn’t get it?</span>
          {/* The countdown and the button share one place; each fades through a blur into the other. */}
          <span className="grid items-center">
            {/* The ticking digits stay out of screen readers; they hear that a resend is coming instead. */}
            <span className="sr-only">
              {left && left > 0 ? "You can resend the code shortly." : ""}
            </span>
            <span
              className="col-start-1 row-start-1 flex items-baseline whitespace-nowrap tabular-nums"
              aria-hidden="true"
              style={{
                opacity: left && left > 0 ? 1 : 0,
                filter: left && left > 0 ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              Resend in 0:
              <NumberRoll
                value={left ?? resendAfter}
                format={{ minimumIntegerDigits: 2 }}
                direction="down"
                duration={700}
              />
            </span>
            <span
              className="col-start-1 row-start-1"
              inert={!!(left && left > 0)}
              style={{
                opacity: left && left > 0 ? 0 : 1,
                filter: left && left > 0 ? "blur(3px)" : "none",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              <StatusButton
                variant="ghost"
                size="sm"
                status={resend}
                labels={{
                  idle: "Resend code",
                  pending: "Sending",
                  success: "Sent",
                  error: "Try again",
                }}
                onClick={doResend}
                className="-ml-2"
              />
            </span>
          </span>
        </div>
      )}

      <p role="status" aria-live="polite" className="sr-only">
        {right
          ? "Code verified"
          : wrong
            ? "That code didn't work. Enter it again."
            : phase === "checking"
              ? "Checking the code"
              : ""}
      </p>
    </div>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * NUMBER ROLL: numbers that change like an odometer
 *
 *   rolling   each digit is a column that rolls to its new
 *             value, in the direction the number moved: going
 *             up, a 9 rolls on to 0 instead of spinning back
 *   places    new places slide open from nothing; lost ones
 *             fold away
 *   format    anything Intl.NumberFormat does: currency,
 *             percent, compact ("1.2K"), decimals
 *
 * The real number is always there as text for screen readers
 * and copy and paste; the columns are only what you see.
 * ───────────────────────────────────────────────────────── */

export interface NumberRollProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  value: number;
  /** Intl.NumberFormat options, e.g. { style: "currency", currency: "USD" }. */
  format?: Intl.NumberFormatOptions;
  locales?: string | string[];
  prefix?: string;
  suffix?: string;
  /** Start from this value and roll to `value` once mounted, e.g. 0 for stats. */
  from?: number;
  /** Roll duration in ms. */
  duration?: number;
  /** Always roll this way, e.g. "down" for a countdown's seconds, which wrap from 00 to 59. Defaults to the way the number moved. */
  direction?: "up" | "down";
}

type Column = { key: string; char: string; digit: number | null };

const EASE = "cubic-bezier(0.16,1,0.3,1)";
const SETS = 5; // the strip repeats 0–9 five times so a roll never runs out of digits
const MIDDLE = 20;
/** The strip as one text node, a digit a line: fifty lines, but one element to lay out instead of fifty. */
const STRIP = Array.from({ length: SETS * 10 }, (_, i) => i % 10).join("\n");

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Digits are keyed by their place counted from the right, so the units column stays the units column. */
function columns(text: string): Column[] {
  const chars = [...text];
  const seen = new Map<string, number>();
  let place = 0;
  const out: Column[] = [];
  for (let i = chars.length - 1; i >= 0; i--) {
    const char = chars[i];
    if (/\d/.test(char))
      out.push({ key: `d${place++}`, char, digit: Number(char) });
    else {
      // Symbols are keyed by how many of the same symbol sit to their right, so a comma that shifts is the same comma.
      const n = seen.get(char) ?? 0;
      seen.set(char, n + 1);
      out.push({ key: `s${char}${n}`, char, digit: null });
    }
  }
  return out.reverse();
}

// Memoised: a parent that re-renders with the same number doesn't rebuild the strips.
const Digit = React.memo(function Digit({
  digit,
  trend,
  duration,
  reduced,
  rollIn,
}: {
  digit: number;
  trend: number;
  duration: number;
  reduced: boolean;
  rollIn: boolean;
}) {
  const [pos, setPos] = React.useState(MIDDLE + (rollIn ? 0 : digit));
  const [moving, setMoving] = React.useState(false);
  const posRef = React.useRef(pos);
  const stripRef = React.useRef<HTMLSpanElement>(null);

  React.useLayoutEffect(() => {
    const current = posRef.current;
    const showing = ((current % 10) + 10) % 10;
    if (showing === digit) return;
    if (reduced) {
      posRef.current = MIDDLE + digit;
      setMoving(false);
      setPos(MIDDLE + digit);
      return;
    }
    const up = trend > 0 || (trend === 0 && digit > showing);
    let target = up
      ? current + ((digit - showing + 10) % 10)
      : current - ((showing - digit + 10) % 10);
    // Values arriving faster than a roll (a progress percent) never let it re-centre, so before it runs off the strip,
    // jump the strip back by whole sets mid-roll (it looks identical) and roll on from there.
    if (target < 10 || target > SETS * 10 - 11) {
      const shift = Math.round((target - MIDDLE) / 10) * 10;
      const strip = stripRef.current;
      if (strip?.offsetHeight) {
        let visual = current;
        try {
          visual =
            -new DOMMatrixReadOnly(getComputedStyle(strip).transform).m42 /
            (strip.offsetHeight / (SETS * 10));
        } catch {}
        const transition = strip.style.transition;
        strip.style.transition = "none";
        strip.style.transform = `translateY(${(-(visual - shift) * 100) / (SETS * 10)}%)`;
        void strip.offsetHeight;
        strip.style.transition = transition;
      }
      target -= shift;
    }
    posRef.current = target;
    setMoving(true);
    setPos(target);
  }, [digit, trend, reduced]);

  // After a roll, quietly re-centre on the middle set so the next roll always has room.
  const settle = () => {
    const centred = MIDDLE + (((posRef.current % 10) + 10) % 10);
    posRef.current = centred;
    setMoving(false);
    setPos(centred);
  };

  return (
    <span className="relative inline-block [clip-path:inset(0)]">
      <span className="invisible">{digit}</span>
      <span
        ref={stripRef}
        aria-hidden="true"
        onTransitionEnd={settle}
        className="absolute inset-x-0 top-0 block whitespace-pre text-center"
        style={{
          transform: `translateY(${(-pos * 100) / (SETS * 10)}%)`,
          transition: moving ? `transform ${duration}ms ${EASE}` : "none",
        }}
      >
        {STRIP}
      </span>
    </span>
  );
});

/** A place that appeared after the first paint slides open; places that were there from the start just sit. */
function Place({
  enter,
  children,
}: {
  enter: boolean;
  children: React.ReactNode;
}) {
  const [entering] = React.useState(enter);
  return (
    <span
      className={`inline-block ${entering ? "[clip-path:inset(0)] animate-[ui-col-in_500ms_cubic-bezier(0.16,1,0.3,1)_both]" : ""}`}
    >
      {children}
    </span>
  );
}

export function NumberRoll({
  value,
  format,
  locales,
  prefix = "",
  suffix = "",
  from,
  duration = 900,
  direction,
  className = "",
  ...props
}: NumberRollProps) {
  const reduced = useReducedMotion();
  const [shown, setShown] = React.useState(from ?? value);
  const previous = React.useRef(shown);
  const mounted = React.useRef(false);

  // Roll from `from` to the real value once on screen (a frame later, so the start is painted).
  React.useEffect(() => {
    const frame = requestAnimationFrame(() => setShown(value));
    return () => cancelAnimationFrame(frame);
  }, [value]);

  React.useEffect(() => {
    mounted.current = true;
  }, []);

  const formatter = React.useMemo(
    () => new Intl.NumberFormat(locales, format),
    [locales, format && JSON.stringify(format)],
  );
  const text = `${prefix}${formatter.format(shown)}${suffix}`;
  const cols = React.useMemo(() => columns(text), [text]);
  const trend =
    direction === "up"
      ? 1
      : direction === "down"
        ? -1
        : Math.sign(shown - previous.current);

  // Places that disappear fold away instead of vanishing.
  const [leaving, setLeaving] = React.useState<Column[]>([]);
  const lastCols = React.useRef(cols);
  React.useLayoutEffect(() => {
    const gone = lastCols.current.filter(
      (c) => !cols.some((n) => n.key === c.key),
    );
    lastCols.current = cols;
    previous.current = shown;
    if (!gone.length || reduced) return;
    setLeaving(gone);
    const timer = window.setTimeout(() => setLeaving([]), 420);
    return () => window.clearTimeout(timer);
  }, [cols, shown, reduced]);

  return (
    <span className={`inline-flex tabular-nums ${className}`} {...props}>
      <span className="sr-only">{`${prefix}${formatter.format(value)}${suffix}`}</span>
      <span
        aria-hidden="true"
        className="inline-flex items-baseline whitespace-pre"
      >
        {leaving.map((c) => (
          <span
            key={`out-${c.key}`}
            className="inline-block [clip-path:inset(0)] animate-[ui-col-out_400ms_cubic-bezier(0.16,1,0.3,1)_forwards]"
          >
            {c.char}
          </span>
        ))}
        {cols.map((c) => (
          <Place key={c.key} enter={mounted.current && !reduced}>
            {c.digit === null ? (
              c.char
            ) : (
              <Digit
                digit={c.digit}
                trend={trend}
                duration={duration}
                reduced={reduced}
                rollIn={mounted.current}
              />
            )}
          </Place>
        ))}
      </span>
    </span>
  );
}

"use client";

import * as React from "react";
import { TextMorph } from "./text-morph";

/* ─────────────────────────────────────────────────────────
 * STATUS BUTTON: a button that tells you what happened
 *
 *   idle     "Save", with an optional icon
 *   pending  a spinner opens in; the label morphs to "Saving"
 *   success  a check draws itself; "Saved"
 *   error    the button gives a small shake; "Try again"
 *
 * Every change is one motion: the icon slot opens and closes,
 * icons swap through a blur, letters the labels share stay put
 * and the button's width eases to fit.
 * ───────────────────────────────────────────────────────── */

export type ActionStatus = "idle" | "pending" | "success" | "error";

export interface StatusButtonProps extends React.ButtonHTMLAttributes<HTMLButtonElement> {
  status?: ActionStatus;
  /** Labels per state; defaults to Save, Saving, Saved, Try again. */
  labels?: Partial<Record<ActionStatus, string>>;
  /** Shown before the label while idle. */
  icon?: React.ReactNode;
  variant?: "primary" | "outline" | "ghost";
  /** "sm" is 28px tall, for toolbars and headers. */
  size?: "default" | "sm";
  /** Called this long after success (ms), e.g. to go back to idle. */
  onReset?: () => void;
  resetAfter?: number;
}

const LABELS: Record<ActionStatus, string> = {
  idle: "Save",
  pending: "Saving",
  success: "Saved",
  error: "Try again",
};
const EASE = "cubic-bezier(0.16,1,0.3,1)";
const FOCUS =
  "focus-visible:outline-none focus-visible:ring-2 focus-visible:ring-ring/40 focus-visible:ring-offset-2 focus-visible:ring-offset-background";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

function Check({ drawn, reduced }: { drawn: boolean; reduced: boolean }) {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <path
        d="M3.5 8.5 6.5 11.5 12.5 4.5"
        stroke="currentColor"
        strokeWidth="2"
        strokeLinecap="round"
        strokeLinejoin="round"
        pathLength={1}
        strokeDasharray={1}
        style={{
          strokeDashoffset: drawn ? 0 : 1,
          transition:
            drawn && !reduced
              ? `stroke-dashoffset 420ms ${EASE} 120ms`
              : "none",
        }}
      />
    </svg>
  );
}

function Alert() {
  return (
    <svg viewBox="0 0 16 16" fill="none">
      <circle cx="8" cy="8" r="6.25" stroke="currentColor" strokeWidth="1.5" />
      <path
        d="M8 4.75v3.75"
        stroke="currentColor"
        strokeWidth="1.75"
        strokeLinecap="round"
      />
      <circle cx="8" cy="11" r="1" fill="currentColor" />
    </svg>
  );
}

export function StatusButton({
  status = "idle",
  labels,
  icon,
  variant = "primary",
  size = "default",
  onReset,
  resetAfter = 1800,
  className = "",
  onClick,
  ...props
}: StatusButtonProps) {
  const reduced = useReducedMotion();
  const ref = React.useRef<HTMLButtonElement>(null);
  const label = { ...LABELS, ...labels }[status];
  const showIcon = status !== "idle" || Boolean(icon);
  const busy = status === "pending";
  const sm = size === "sm";
  const iconSize = sm ? 14 : 16;

  // A short shake when it fails: the eye catches it even if you looked away.
  React.useEffect(() => {
    if (status !== "error" || reduced) return;
    ref.current?.animate(
      [
        { transform: "none" },
        { transform: "translateX(-4px)" },
        { transform: "translateX(4px)" },
        { transform: "translateX(-2px)" },
        { transform: "none" },
      ],
      { duration: 380, easing: "ease-out" },
    );
  }, [status, reduced]);

  React.useEffect(() => {
    if (status !== "success" || !onReset) return;
    const timer = window.setTimeout(onReset, resetAfter);
    return () => window.clearTimeout(timer);
  }, [status, onReset, resetAfter]);

  const tone =
    status === "error"
      ? "bg-red-500/10 text-red-600 shadow-[inset_0_0_0_1px_color-mix(in_oklab,var(--color-red-500)_30%,transparent)] dark:text-red-400"
      : variant === "primary"
        ? "bg-primary text-primary-foreground hover:bg-primary/90"
        : variant === "ghost"
          ? `hover:bg-accent hover:text-foreground ${status === "idle" ? "text-muted-foreground" : "text-foreground"}`
          : "text-foreground shadow-[inset_0_0_0_1px_var(--border)] hover:bg-accent";

  const icons: Record<ActionStatus, React.ReactNode> = {
    idle: icon,
    // Spins only while pending, so a hidden spinner never keeps the page busy.
    pending: (
      <span
        className={`${sm ? "size-3" : "size-3.5"} rounded-full border-[1.5px] border-current border-t-transparent opacity-80 motion-reduce:animate-none ${status === "pending" ? "animate-spin" : ""}`}
      />
    ),
    success: <Check drawn={status === "success"} reduced={reduced} />,
    error: <Alert />,
  };

  return (
    <>
      <button
        ref={ref}
        type="button"
        aria-busy={busy || undefined}
        aria-disabled={busy || undefined}
        onClick={(e) => {
          if (busy) return e.preventDefault();
          onClick?.(e);
        }}
        className={`cursor-pointer disabled:cursor-default aria-disabled:cursor-default inline-flex items-center justify-center whitespace-nowrap rounded-full font-medium transition-[background-color,color,box-shadow,scale,padding] duration-300 active:scale-[0.97] motion-reduce:active:scale-100 ${
          sm
            ? `h-7 text-[12px] ${variant === "ghost" ? "px-2.5" : "px-3"}`
            : "h-9 px-4 text-[13px]"
        } ${FOCUS} ${tone} ${className}`}
        {...props}
      >
        <span
          aria-hidden="true"
          className={`relative flex shrink-0 items-center justify-center ${sm ? "h-3.5 [&_svg]:size-3.5" : "h-4 [&_svg]:size-4"}`}
          style={{
            width: showIcon ? iconSize : 0,
            marginRight: showIcon ? (sm ? 5 : 6) : 0,
            transition: reduced
              ? "none"
              : `width 380ms ${EASE}, margin 380ms ${EASE}`,
          }}
        >
          {(Object.keys(icons) as ActionStatus[]).map((s) => (
            <span
              key={s}
              className="absolute inset-0 flex items-center justify-center"
              style={{
                opacity: s === status ? 1 : 0,
                transform: s === status ? "none" : "scale(0.6)",
                filter: s === status ? "none" : "blur(3px)",
                transition: reduced
                  ? "none"
                  : `opacity 260ms ${EASE}, transform 380ms ${EASE}, filter 260ms ${EASE}`,
              }}
            >
              {icons[s]}
            </span>
          ))}
        </span>
        <TextMorph>{label}</TextMorph>
      </button>
      {/* Outside the button, so the announcement isn't read as part of its name. */}
      <span className="sr-only" role="status">
        {status === "idle" ? "" : label}
      </span>
    </>
  );
}

"use client";

import * as React from "react";

/* ─────────────────────────────────────────────────────────
 * TEXT MORPH: text that changes the way it should
 *
 *   shared   letters both texts share stay alive and slide to
 *            their new place ("Save" → "Saving" keeps "Sav")
 *   new      letters that weren't there rise in out of a blur,
 *            one after another
 *   gone     letters that leave lift away and blur out where
 *            they stood
 *   width    the box eases to its new width, so a button or
 *            pill holding it resizes with it
 *
 * Texts with little in common crossfade as a whole instead of
 * flinging single letters across. The real text is always
 * there for screen readers.
 * ───────────────────────────────────────────────────────── */

export interface TextMorphProps extends Omit<
  React.HTMLAttributes<HTMLSpanElement>,
  "children"
> {
  children: string;
  /** Morph time in ms. */
  duration?: number;
  /** Where new letters come from: below ("up") or above ("down"). */
  direction?: "up" | "down";
  /** Ease the box's width too; turn off for text that wraps. */
  animateWidth?: boolean;
}

type Glyph = { key: number; char: string };
type Leaving = Glyph & { x: number; y: number };

const EASE = "cubic-bezier(0.16,1,0.3,1)";

const reducedQuery = "(prefers-reduced-motion: reduce)";
const subscribeReduced = (onChange: () => void) => {
  const query = window.matchMedia(reducedQuery);
  query.addEventListener("change", onChange);
  return () => query.removeEventListener("change", onChange);
};
const useReducedMotion = () =>
  React.useSyncExternalStore(
    subscribeReduced,
    () => window.matchMedia(reducedQuery).matches,
    () => false,
  );

/** Keep the letters two texts share (longest common subsequence); everything else is new. */
function morph(
  previous: Glyph[],
  text: string,
  nextKey: () => number,
): Glyph[] {
  const a = previous.map((g) => g.char);
  const b = Array.from(text);
  const fresh = () => b.map((char) => ({ key: nextKey(), char }));
  if (!a.length || !b.length) return fresh();

  const dp = Array.from(
    { length: a.length + 1 },
    () => new Uint16Array(b.length + 1),
  );
  for (let i = a.length - 1; i >= 0; i--)
    for (let j = b.length - 1; j >= 0; j--)
      dp[i][j] =
        a[i] === b[j]
          ? dp[i + 1][j + 1] + 1
          : Math.max(dp[i + 1][j], dp[i][j + 1]);

  // Too little in common reads as two different words: crossfade them instead.
  if (dp[0][0] < Math.min(a.length, b.length) * 0.5) return fresh();

  const out: Glyph[] = [];
  let i = 0;
  let j = 0;
  while (j < b.length) {
    if (i < a.length && a[i] === b[j]) {
      out.push(previous[i++]);
      j++;
    } else if (i < a.length && dp[i + 1][j] >= dp[i][j + 1]) i++;
    else out.push({ key: nextKey(), char: b[j++] });
  }
  return out;
}

function LeavingGlyph({
  glyph,
  lift,
  duration,
  onDone,
}: {
  glyph: Leaving;
  lift: number;
  duration: number;
  onDone: (key: number) => void;
}) {
  const ref = React.useRef<HTMLSpanElement>(null);
  React.useLayoutEffect(() => {
    const el = ref.current;
    if (!el) return;
    const animation = el.animate(
      [
        { opacity: 1, filter: "blur(0px)", transform: "none" },
        { opacity: 0, filter: "blur(4px)", transform: `translateY(${lift}em)` },
      ],
      { duration: duration * 0.6, easing: EASE, fill: "forwards" },
    );
    animation.onfinish = () => onDone(glyph.key);
    return () => animation.cancel();
  }, [glyph.key, lift, duration, onDone]);
  return (
    <span
      ref={ref}
      aria-hidden="true"
      className="pointer-events-none absolute whitespace-pre"
      style={{ left: glyph.x, top: glyph.y }}
    >
      {glyph.char}
    </span>
  );
}

export function TextMorph({
  children: text,
  duration = 460,
  direction = "up",
  animateWidth = true,
  className = "",
  ...props
}: TextMorphProps) {
  const reduced = useReducedMotion();
  const counter = React.useRef(text.length);
  const nextKey = React.useCallback(() => ++counter.current, []);
  const [glyphs, setGlyphs] = React.useState<Glyph[]>(() =>
    Array.from(text).map((char, i) => ({ key: i + 1, char })),
  );
  const [leaving, setLeaving] = React.useState<Leaving[]>([]);
  const rootRef = React.useRef<HTMLSpanElement>(null);
  const els = React.useRef(new Map<number, HTMLSpanElement>());
  const before = React.useRef<{
    at: Map<number, { x: number; y: number }>;
    width: number;
  } | null>(null);
  const rise = direction === "up" ? 0.35 : -0.35;

  // A preference change must also finish an in-flight morph whose target text
  // already matches the glyphs (including the empty label in a folded receipt).
  React.useLayoutEffect(() => {
    if (!reduced) return;
    before.current = null;
    const root = rootRef.current;
    root
      ?.getAnimations({ subtree: true })
      .forEach((animation) => animation.cancel());
    if (root) root.style.whiteSpace = "";
    setLeaving((previous) => (previous.length ? [] : previous));
  }, [reduced]);

  // 1. The text changed: note where every letter stands, then work out which letters stay.
  React.useLayoutEffect(() => {
    if (text === glyphs.map((g) => g.char).join("")) return;
    const root = rootRef.current;
    if (!root || reduced) {
      setLeaving([]);
      setGlyphs(Array.from(text).map((char) => ({ key: nextKey(), char })));
      return;
    }
    const box = root.getBoundingClientRect();
    const at = new Map<number, { x: number; y: number }>();
    els.current.forEach((el, key) => {
      const r = el.getBoundingClientRect();
      at.set(key, { x: r.left - box.left, y: r.top - box.top });
    });
    before.current = { at, width: box.width };
    const next = morph(glyphs, text, nextKey);
    const kept = new Set(next.map((g) => g.key));
    setLeaving((l) => [
      ...l,
      ...glyphs
        .filter((g) => !kept.has(g.key))
        .map((g) => ({ ...g, ...(at.get(g.key) ?? { x: 0, y: 0 }) })),
    ]);
    setGlyphs(next);
  }, [text, reduced]);

  // 2. The new letters are in place: glide the ones that stayed, raise the new ones, ease the width.
  React.useLayoutEffect(() => {
    const prev = before.current;
    const root = rootRef.current;
    if (!prev || !root) return;
    before.current = null;
    const box = root.getBoundingClientRect();
    let order = 0;
    for (const g of glyphs) {
      const el = els.current.get(g.key);
      if (!el) continue;
      const from = prev.at.get(g.key);
      if (from) {
        const r = el.getBoundingClientRect();
        const dx = from.x - (r.left - box.left);
        const dy = from.y - (r.top - box.top);
        if (Math.abs(dx) > 0.5 || Math.abs(dy) > 0.5)
          el.animate(
            [
              { transform: `translate(${dx}px, ${dy}px)` },
              { transform: "none" },
            ],
            { duration, easing: EASE },
          );
      } else {
        el.animate(
          [
            {
              opacity: 0,
              filter: "blur(4px)",
              transform: `translateY(${rise}em)`,
            },
            { opacity: 1, filter: "blur(0px)", transform: "none" },
          ],
          {
            duration,
            easing: EASE,
            delay: Math.min(order++ * 16, 160),
            fill: "backwards",
          },
        );
      }
    }
    if (animateWidth && Math.abs(prev.width - box.width) > 0.5) {
      // Hold the words on one line while the box is narrower than them, or "No credits left" would wrap mid-morph.
      root.style.whiteSpace = "nowrap";
      const resize = root.animate(
        [{ width: `${prev.width}px` }, { width: `${box.width}px` }],
        { duration, easing: EASE },
      );
      resize.onfinish = resize.oncancel = () => {
        root.style.whiteSpace = "";
      };
    }
  }, [glyphs, duration, rise, animateWidth]);

  const done = React.useCallback(
    (key: number) => setLeaving((l) => l.filter((g) => g.key !== key)),
    [],
  );

  // Words stay unbroken; lines may only wrap at spaces.
  const words: Glyph[][] = [];
  for (const g of glyphs) {
    if (
      g.char === " " ||
      !words.length ||
      words[words.length - 1][0]?.char === " "
    )
      words.push([g]);
    else words[words.length - 1].push(g);
  }

  return (
    <span
      ref={rootRef}
      className={`relative inline-block ${className}`}
      {...props}
    >
      <span className="sr-only">{text}</span>
      {words.map((word, w) => (
        <span
          key={w}
          aria-hidden="true"
          className="inline-block whitespace-pre"
        >
          {word.map((g) => (
            <span
              key={g.key}
              ref={(el) => {
                if (el) els.current.set(g.key, el);
                else els.current.delete(g.key);
              }}
              className="inline-block"
            >
              {g.char}
            </span>
          ))}
        </span>
      ))}
      {leaving.map((g) => (
        <LeavingGlyph
          key={`out-${g.key}`}
          glyph={g}
          lift={-rise}
          duration={duration}
          onDone={done}
        />
      ))}
    </span>
  );
}

